import{_ as a,o as n,c as p,a6 as e}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"跨境SKU任务清单与批量复用","description":"","frontmatter":{"id":"P19","title":"跨境SKU任务清单与批量复用","chapter":"13","topic":"cross-border","status":"已公开","evidence_status":"完整模板，尚未执行图像任务或流程验证","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills","ecommerce-image-toolkit"],"order":119},"headers":[],"relativePath":"prompts/P19.md","filePath":"prompts/P19.md"}'),t={name:"prompts/P19.md"};function l(i,s,o,c,r,d){return n(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="p19-跨境sku任务清单与批量复用" tabindex="-1">P19 跨境SKU任务清单与批量复用 <a class="header-anchor" href="#p19-跨境sku任务清单与批量复用" aria-label="Permalink to &quot;P19 跨境SKU任务清单与批量复用&quot;">​</a></h1><p>类型：批量规划。替换项目：SKU事实、对应照片、市场、语言、位置与任务ID。下面提供完整填写示范，虚构商品DN01只作练习；正式使用时替换事实与素材。示范未附照片、未执行任务。</p><p><a href="/ai-visual-creation-handbook/ecommerce/cross-border-sku-delivery">逐步教程</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请制作跨境SKU批量任务清单，本次只做计划和逐项指令，不提交图像生成。</span></span>
<span class="line"><span>以下DN01／DeskNest是虚构练习数据，不代表实际品牌或商品；正式任务必须换成已核实的商品记录。</span></span>
<span class="line"><span>练习事实：带盖桌面收纳盒；白色ABS；外尺寸长220×宽150×高120 mm；可拆隔板1个。</span></span>
<span class="line"><span>发货内容：盒体1、盖子1、隔板1。文具等场景道具不随商品发货。</span></span>
<span class="line"><span>容积、耐温、承重、防水、食品接触、认证和回收属性均未知，不补相关声明。</span></span>
<span class="line"><span>图片输入如有：图1是真实商品外观依据；图2是实际细节；图3仅参考背景和构图，不使用其商品、Logo或参数。</span></span>
<span class="line"><span>未附实拍时先给素材清单和可执行方案；不要臆画正式商品或未拍摄结构。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>增加一个独立虚构练习SKU DN01-G：灰色，与DN01-W白色具有相同练习外尺寸和结构；正式执行时两者各有自己的真实照片，不靠染色伪造。</span></span>
<span class="line"><span>目标组合：Amazon US主图及尺寸副图；Shopify英文产品首图；Shopee SG封面。每个SKU分别生成对应任务记录。</span></span>
<span class="line"><span>清单字段：task_id、sku、market、language、position、source_asset、事实记录、完整任务词、目标尺寸、准确文案版本、status、实际结果、返工说明。</span></span>
<span class="line"><span>共用视觉段固定：真实主体、干净背景、清晰外观与准确文字；变量段仅使用当前SKU照片、颜色、市场位置和文案。</span></span>
<span class="line"><span>先选DN01-W的一张主图完成检查，再扩展；主图与广告或详情的文字规则不得混用。</span></span>
<span class="line"><span>中断时先查原task_id与结果状态，不默认任务没执行而重复提交。</span></span>
<span class="line"><span>每一项都给可独立复制的任务词；计划路径标“计划”，不存在文件不能写已交付。</span></span>
<span class="line"><span>本次范围按上述任务执行；没有图像能力时只交方案并写明状态。</span></span>
<span class="line"><span>实际执行时保留真实商品层与准确文字，逐项核对形状、颜色、盖子、隔板、配件、单位和文字。</span></span>
<span class="line"><span>目标尺寸与工具实际输出分别报告；不把画质形容词、计划路径或未创建的PSD当作已交付结果。</span></span>
<span class="line"><span>最终列：已完成、需要补的素材、无法确认的项目、实际存在的文件与下一步。</span></span></code></pre></div><p>检查：输入角色清楚、事实与未知分开、输出范围明确，实际文件与后台状态据实记录。</p>`,5)])])}const u=a(t,[["render",l]]);export{_ as __pageData,u as default};
